const $=s=>document.querySelector(s), fmt=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='wv-orcamentos-v1',colors=['#719df3','#d5a44f','#8d7be0','#54a6ad','#65a38c','#a1a9b6'];let records=[],view='board',editing=null,toastTimer;
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function seed(){const t=WV.today(),relative=n=>{const d=new Date(t+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};return [
['Oficina Horizonte','Revisão dos computadores','Novo',0,28000,'Diagnóstico e revisão'],['Studio Aurora','Site de apresentação','Orçado',0,145000,'Criação da página comercial'],['Café do Pátio','Organização de planilha de vendas','Orçado',2,65000,'Relatório e organização da base'],['Ateliê Linha Clara','Catálogo de produtos','Aprovado',1,89000,'Catálogo digital'],['Clínica Exemplo','Painel de atendimentos','Em execução',-1,125000,'Protótipo do painel'],['Loja Bons Ventos','Relatório mensal','Concluído',-3,48000,'Relatório de vendas']
].map((a,i)=>({id:'DEMO-'+String(i+1).padStart(3,'0'),client:a[0],contact:'contato fictício',service:a[1],status:a[2],followup:relative(a[3]),validity:relative(7),owner:'Wandley',notes:'Atendimento fictício para explorar o fluxo. Valores ilustrativos.',created:t,items:[{description:a[5],qty:1,cents:a[4]}]}))}
function save(next){try{localStorage.setItem(KEY,JSON.stringify({schema:1,records:next}));records=next;render();return true}catch(e){notify('Não foi possível salvar no navegador. Exporte um backup e confira o espaço disponível.');return false}}
try{const raw=localStorage.getItem(KEY);records=raw?WV.backup(JSON.parse(raw)):seed();if(!raw)localStorage.setItem(KEY,JSON.stringify({schema:1,records}))}catch(e){records=[];notify('Os dados locais não puderam ser lidos. Importe um backup ou restaure os exemplos. Nenhum dado foi sobrescrito.')}
const due=r=>!WV.closed(r)&&r.followup&&r.followup<=WV.today();
function dateLabel(s){return s?s.split('-').reverse().join('/'):'Sem retorno definido'}
function render(){const sum=arr=>arr.reduce((n,r)=>n+WV.total(r),0),open=records.filter(r=>r.status==='Orçado'),done=records.filter(r=>r.status==='Concluído');$('#stat-value').textContent=fmt(sum(open));$('#stat-work').textContent=records.filter(r=>['Aprovado','Em execução'].includes(r.status)).length;$('#stat-return').textContent=records.filter(due).length;$('#return-count').textContent=records.filter(due).length;$('#stat-done').textContent=done.length;$('#stat-done-value').textContent=fmt(sum(done))+' em propostas';
const term=$('#search').value.trim().toLocaleLowerCase('pt-BR'),filter=$('#status-filter').value;let list=records.filter(r=>(!term||(r.client+' '+r.service).toLocaleLowerCase('pt-BR').includes(term))&&(!filter||r.status===filter));if(view==='returns')list=list.filter(r=>!WV.closed(r)&&r.followup).sort((a,b)=>a.followup.localeCompare(b.followup));$('#record-count').textContent=list.length;$('#empty').hidden=list.length>0;
const groups=view==='returns'?[['Retornos pendentes',list,'#54a6ad']]:WV.stages.filter(s=>!filter||s===filter).map((s,i)=>[s,list.filter(r=>r.status===s),colors[WV.stages.indexOf(s)]]);$('#board').innerHTML=groups.map(([stage,rows,color])=>`<section class="column" aria-label="${stage}"><div class="column-head" style="--stage:${color}"><i></i>${stage}<span>${rows.length}</span></div>${rows.length?rows.map(r=>`<article class="card"><div class="card-top"><span>${esc(r.id.startsWith('DEMO-')?r.id:'ORÇ · '+r.id.slice(0,8).toUpperCase())}</span><button data-edit="${esc(r.id)}" aria-label="Abrir ${esc(r.service)}">↗</button></div><h3>${esc(r.service)}</h3><div class="client">${esc(r.client)}</div><div class="card-value">${fmt(WV.total(r))}</div><div class="card-bottom"><span class="due ${due(r)?'urgent':''}">${WV.closed(r)?'Encerrado':r.followup?(due(r)?'◷ ':'')+dateLabel(r.followup):'Sem retorno'}</span><select aria-label="Etapa de ${esc(r.service)}" data-status="${esc(r.id)}">${WV.stages.map(s=>`<option${s===r.status?' selected':''}>${s}</option>`).join('')}</select></div></article>`).join(''):'<div class="column-empty">Nenhum atendimento nesta etapa</div>'}</section>`).join('')}
$('#board').addEventListener('click',e=>{const b=e.target.closest('[data-edit]');if(b)openEditor(records.find(r=>r.id===b.dataset.edit))});$('#board').addEventListener('change',e=>{if(e.target.dataset.status){const next=records.map(r=>r.id===e.target.dataset.status?WV.record({...r,status:e.target.value}):r);if(save(next))notify('Etapa atualizada.')}});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('#page-title').textContent=view==='returns'?'Uma boa conversa tem continuidade.':'Cada pedido, um próximo passo.';$('#page-desc').textContent=view==='returns'?'Retornos agendados, dos mais antigos aos mais próximos.':'Organize propostas e acompanhe o que precisa da sua atenção.';$('#breadcrumb').textContent=view==='returns'?'Próximos retornos':'Atendimentos';$('#section-title').textContent=view==='returns'?'Sua agenda de retornos':'Visão dos atendimentos';render()});$('#search').oninput=render;$('#status-filter').onchange=render;
function itemRow(item={description:'',qty:1,cents:0}){const div=document.createElement('div');div.className='item';div.innerHTML=`<label>Descrição<input class="description" required maxlength="140" value="${esc(item.description)}" placeholder="Serviço ou produto"></label><label>Qtd.<input class="qty" type="number" min="1" max="1000" step="1" required value="${item.qty}"></label><label>Valor unit. (R$)<input class="price" inputmode="decimal" required value="${(item.cents/100).toFixed(2).replace('.',',')}"></label><button type="button" class="remove" aria-label="Remover item">×</button>`;div.querySelector('.remove').onclick=()=>{if($('#items').children.length===1){notify('Mantenha pelo menos um item na proposta.');return}div.remove();updateTotal()};div.addEventListener('input',updateTotal);$('#items').append(div)}
function getItems(){return [...document.querySelectorAll('.item')].map(el=>({description:el.querySelector('.description').value,qty:Number(el.querySelector('.qty').value),cents:WV.cents(el.querySelector('.price').value)}))}
function updateTotal(){try{const items=getItems();if(items.some(i=>!Number.isInteger(i.qty)||i.qty<1||i.qty>1000))throw Error();$('#form-total').textContent=fmt(WV.total({items}))}catch{$('#form-total').textContent='Confira os valores'}}
function openEditor(r){editing=r?.id||null;$('#form').reset();$('#editor-title').textContent=r?'Detalhes do atendimento':'Novo atendimento';$('#form-error').textContent='';for(const k of ['client','contact','service','status','followup','validity','owner','notes'])$('#form').elements.namedItem(k).value=r?.[k]??(k==='status'?'Novo':'');$('#items').replaceChildren();(r?.items||[{description:'',qty:1,cents:0}]).forEach(itemRow);updateTotal();$('#editor').showModal();$('#form').elements.namedItem('client').focus()}
$('#new').onclick=()=>openEditor();$('#close').onclick=$('#cancel').onclick=()=>$('#editor').close();$('#add-item').onclick=()=>{if($('#items').children.length>=30){notify('O limite é de 30 itens por proposta.');return}itemRow();updateTotal()};
function readForm(){const f=$('#form').elements,o={id:editing||crypto.randomUUID(),created:records.find(r=>r.id===editing)?.created||WV.today(),items:getItems()};for(const k of ['client','contact','service','status','followup','validity','owner','notes'])o[k]=f.namedItem(k).value;return WV.record(o)}
$('#form').onsubmit=e=>{e.preventDefault();try{const r=readForm(),next=editing?records.map(x=>x.id===editing?r:x):[r,...records];if(next.length>1000)throw Error('Limite de 1000 atendimentos nesta demonstração.');if(save(next)){$('#editor').close();notify(editing?'Atendimento atualizado.':'Atendimento criado.')}}catch(err){$('#form-error').textContent=err.message}};
$('#print').onclick=()=>{if(!$('#form').reportValidity())return;let r;try{r=readForm()}catch(err){$('#form-error').textContent=err.message;return}const w=window.open('','_blank');if(!w){notify('Permita abrir a prévia da proposta neste navegador.');return}w.opener=null;w.document.write(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Orçamento · ${esc(r.client)}</title><style>body{font:15px Arial;color:#17283e;max-width:780px;margin:50px auto;padding:25px}h1{font-size:30px}small{color:#64748b}table{width:100%;border-collapse:collapse;margin:35px 0}td,th{padding:14px 7px;text-align:left;border-bottom:1px solid #dce4ee}td:last-child,th:last-child{text-align:right}.notes{white-space:pre-wrap;line-height:1.7}button{padding:12px;border:0;background:#2563eb;color:#fff;border-radius:5px}@media print{button{display:none}body{margin:0}}</style><small>WV.LAB / PROPOSTA DEMONSTRATIVA</small><h1>${esc(r.service)}</h1><p><strong>Cliente:</strong> ${esc(r.client)}<br><strong>Contato:</strong> ${esc(r.contact||'Não informado')}<br><strong>Responsável:</strong> ${esc(r.owner||'Não informado')}<br><strong>Validade:</strong> ${dateLabel(r.validity)}</p><table><thead><tr><th>Item</th><th>Qtd.</th><th>Unitário</th><th>Subtotal</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.qty}</td><td>${fmt(i.cents)}</td><td>${fmt(i.qty*i.cents)}</td></tr>`).join('')}</tbody></table><h2>Total: ${fmt(WV.total(r))}</h2><p class="notes">${esc(r.notes)}</p><small>Prévia dos campos atuais. Salve o atendimento para registrar alterações. Esta versão não envia propostas nem registra aceite eletrônico.</small><p><button onclick="window.print()">Imprimir / salvar como PDF</button></p></html>`);w.document.close()};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({schema:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wv-orcamentos-'+WV.today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup exportado. Guarde o arquivo em local seguro.')};$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Escolha um backup de até 2 MB.');const incoming=WV.backup(JSON.parse(await file.text()));const merged=new Map(records.map(r=>[r.id,r]));for(const r of incoming)merged.set(r.id,r);if(merged.size>1000)throw Error('A importação excede o limite de 1000 atendimentos.');if(!window.confirm('Importar '+incoming.length+' atendimentos? Registros com o mesmo identificador serão substituídos. Exporte um backup antes se precisar preservar a versão atual.'))return;if(save([...merged.values()]))notify('Backup importado.')}catch(err){notify(err.message||'Não foi possível importar o arquivo.')}finally{e.target.value=''}};
$('#reset').onclick=()=>$('#confirm-dialog').showModal();$('#keep').onclick=()=>$('#confirm-dialog').close();$('#confirm-reset').onclick=()=>{if(save(seed())){$('#confirm-dialog').close();notify('Exemplos restaurados.')}};window.addEventListener('storage',e=>{if(e.key===KEY){try{records=e.newValue?WV.backup(JSON.parse(e.newValue)):[];render();notify('Dados atualizados por outra aba.')}catch{notify('Não foi possível ler a atualização de outra aba.')}}});render();
